// Сарфи феълҳо: 22 боби аслӣ (6 сулосии муҷаррад, 12 сулосии мазид, 1 рубоии муҷаррад, 3 рубоии мазид).
// Conjugations are generated by rule for sound (ṣaḥīḥ sālim) verbs; a few doubled/hamzated
// verbs in the rare abwāb carry their ṣarf ṣaghīr explicitly instead.

const a = "َ", u = "ُ", i = "ِ", o = "ْ", sh = "ّ", un = "ٌ", an = "ً", in_ = "ٍ";

// ---------- abwāb ----------
// mv/mu: vowel of ʿayn in māḍī / muḍāriʿ (mujarrad only)
const MUJ = { 1: ["a", "u", "نَصَرَ يَنْصُرُ"], 2: ["a", "i", "ضَرَبَ يَضْرِبُ"], 3: ["i", "a", "سَمِعَ يَسْمَعُ"], 4: ["a", "a", "فَتَحَ يَفْتَحُ"], 5: ["u", "u", "كَرُمَ يَكْرُمُ"], 6: ["i", "i", "حَسِبَ يَحْسِبُ"] };
const V = { a, u, i };

