/** Stems for a root in a bāb. Every stem is given WITHOUT its final vowel. */
function stems(bab, r, masdarMuj) {
  const [F, A, L, Q] = r;
  if (bab <= 6) {
    const [mv, mu] = MUJ[bab];
    return {
      madi: F + a + A + V[mv] + L, madiM: F + u + A + i + L,
      mud: F + o + A + V[mu] + L, pv: a, mudM: F + o + A + a + L,
      amr: (mu === "u" ? "اُ" : "اِ") + F + o + A + V[mu] + L,
      masdar: masdarMuj, fail: F + a + "ا" + A + i + L, maful: "مَ" + F + o + A + u + "و" + L,
      zarf: "مَ" + F + o + A + (mu === "i" ? i : a) + L + un, alat: "مِ" + F + o + A + a + L + un, tafdil: "أَ" + F + o + A + a + L + u,
    };
  }
  const T = {
    7: { madi: "أَ" + F + o + A + a + L, madiM: "أُ" + F + o + A + i + L, mud: F + o + A + i + L, pv: u, mudM: F + o + A + a + L, amr: "أَ" + F + o + A + i + L, masdar: "إِ" + F + o + A + a + "ا" + L + un, fail: "مُ" + F + o + A + i + L, maful: "مُ" + F + o + A + a + L },
    8: { madi: F + a + A + sh + a + L, madiM: F + u + A + sh + i + L, mud: F + a + A + sh + i + L, pv: u, mudM: F + a + A + sh + a + L, amr: F + a + A + sh + i + L, masdar: "تَ" + F + o + A + i + "ي" + L + un, fail: "مُ" + F + a + A + sh + i + L, maful: "مُ" + F + a + A + sh + a + L },
    9: { madi: F + a + "ا" + A + a + L, madiM: F + u + "و" + A + i + L, mud: F + a + "ا" + A + i + L, pv: u, mudM: F + a + "ا" + A + a + L, amr: F + a + "ا" + A + i + L, masdar: "مُ" + F + a + "ا" + A + a + L + a + "ةٌ", fail: "مُ" + F + a + "ا" + A + i + L, maful: "مُ" + F + a + "ا" + A + a + L },
    10: { madi: "اِ" + F + o + "تَ" + A + a + L, madiM: "اُ" + F + o + "تُ" + A + i + L, mud: F + o + "تَ" + A + i + L, pv: a, mudM: F + o + "تَ" + A + a + L, amr: "اِ" + F + o + "تَ" + A + i + L, masdar: "اِ" + F + o + "تِ" + A + a + "ا" + L + un, fail: "مُ" + F + o + "تَ" + A + i + L, maful: "مُ" + F + o + "تَ" + A + a + L },
    11: { madi: "اِنْ" + F + a + A + a + L, madiM: "اُنْ" + F + u + A + i + L, mud: "نْ" + F + a + A + i + L, pv: a, mudM: "نْ" + F + a + A + a + L, amr: "اِنْ" + F + a + A + i + L, masdar: "اِنْ" + F + i + A + a + "ا" + L + un, fail: "مُنْ" + F + a + A + i + L, maful: "مُنْ" + F + a + A + a + L },
    13: { madi: "تَ" + F + a + A + sh + a + L, madiM: "تُ" + F + u + A + sh + i + L, mud: "تَ" + F + a + A + sh + a + L, pv: a, mudM: "تَ" + F + a + A + sh + a + L, amr: "تَ" + F + a + A + sh + a + L, masdar: "تَ" + F + a + A + sh + u + L + un, fail: "مُتَ" + F + a + A + sh + i + L, maful: "مُتَ" + F + a + A + sh + a + L },
    14: { madi: "تَ" + F + a + "ا" + A + a + L, madiM: "تُ" + F + u + "و" + A + i + L, mud: "تَ" + F + a + "ا" + A + a + L, pv: a, mudM: "تَ" + F + a + "ا" + A + a + L, amr: "تَ" + F + a + "ا" + A + a + L, masdar: "تَ" + F + a + "ا" + A + u + L + un, fail: "مُتَ" + F + a + "ا" + A + i + L, maful: "مُتَ" + F + a + "ا" + A + a + L },
    15: { madi: "اِسْتَ" + F + o + A + a + L, madiM: "اُسْتُ" + F + o + A + i + L, mud: "سْتَ" + F + o + A + i + L, pv: a, mudM: "سْتَ" + F + o + A + a + L, amr: "اِسْتَ" + F + o + A + i + L, masdar: "اِسْتِ" + F + o + A + a + "ا" + L + un, fail: "مُسْتَ" + F + o + A + i + L, maful: "مُسْتَ" + F + o + A + a + L },
    16: { madi: "اِ" + F + o + A + a + "وْ" + A + a + L, madiM: "اُ" + F + o + A + u + "و" + A + i + L, mud: F + o + A + a + "وْ" + A + i + L, pv: a, mudM: F + o + A + a + "وْ" + A + a + L, amr: "اِ" + F + o + A + a + "وْ" + A + i + L, masdar: "اِ" + F + o + A + i + "ي" + A + a + "ا" + L + un, fail: "مُ" + F + o + A + a + "وْ" + A + i + L, maful: "مُ" + F + o + A + a + "وْ" + A + a + L },
    17: { madi: "اِ" + F + o + A + a + "وَّ" + L, madiM: "اُ" + F + o + A + u + "وِّ" + L, mud: F + o + A + a + "وِّ" + L, pv: a, mudM: F + o + A + a + "وَّ" + L, amr: "اِ" + F + o + A + a + "وِّ" + L, masdar: "اِ" + F + o + A + i + "وَّا" + L + un, fail: "مُ" + F + o + A + a + "وِّ" + L, maful: "مُ" + F + o + A + a + "وَّ" + L },
    19: { madi: F + a + A + o + L + a + Q, madiM: F + u + A + o + L + i + Q, mud: F + a + A + o + L + i + Q, pv: u, mudM: F + a + A + o + L + a + Q, amr: F + a + A + o + L + i + Q, masdar: F + a + A + o + L + a + Q + a + "ةٌ", fail: "مُ" + F + a + A + o + L + i + Q, maful: "مُ" + F + a + A + o + L + a + Q },
    20: { madi: "تَ" + F + a + A + o + L + a + Q, madiM: "تُ" + F + u + A + o + L + i + Q, mud: "تَ" + F + a + A + o + L + a + Q, pv: a, mudM: "تَ" + F + a + A + o + L + a + Q, amr: "تَ" + F + a + A + o + L + a + Q, masdar: "تَ" + F + a + A + o + L + u + Q + un, fail: "مُتَ" + F + a + A + o + L + i + Q, maful: "مُتَ" + F + a + A + o + L + a + Q },
    21: { madi: "اِ" + F + o + A + a + "نْ" + L + a + Q, madiM: "اُ" + F + o + A + u + "نْ" + L + i + Q, mud: F + o + A + a + "نْ" + L + i + Q, pv: a, mudM: F + o + A + a + "نْ" + L + a + Q, amr: "اِ" + F + o + A + a + "نْ" + L + i + Q, masdar: "اِ" + F + o + A + i + "نْ" + L + a + "ا" + Q + un, fail: "مُ" + F + o + A + a + "نْ" + L + i + Q, maful: "مُ" + F + o + A + a + "نْ" + L + a + Q },
  }[bab];
  if (!T) return null;
  // ism zamān/makān of mazīd = ism mafʿūl; ālat and tafḍīl are formed only from mujarrad
  return { ...T, zarf: T.maful + un, alat: null, tafdil: "أَشَدُّ " + (T.masdar.endsWith("ةٌ") ? T.masdar.slice(0, -1) + "ً" : T.masdar.slice(0, -1) + an + "ا") };
}

