// ---------- Tajik ----------
const VOWELS = "аоуӯеиӣэяю";
const lastWord = (s) => { const k = s.lastIndexOf(" "); return k < 0 ? ["", s] : [s.slice(0, k + 1), s.slice(k + 1)]; };
const endsVowel = (w) => VOWELS.includes(w.slice(-1));
function tjPresent(s, person) { // person: 1s 2s 3s 1p 2p 3p
  const [pre, w] = lastWord(s);
  const v = endsVowel(w);
  const end = { "1s": v ? "ям" : "ам", "2s": "ӣ", "3s": v ? "яд" : "ад", "1p": "ем", "2p": "ед", "3p": v ? "янд" : "анд" }[person];
  return pre + "ме" + w + end;
}
const tjPast = (p, person) => p + { "1s": "ам", "2s": "ӣ", "3s": "", "1p": "ем", "2p": "ед", "3p": "анд" }[person];
const tjPart = (p) => p + "а";
// verbs with a prefix (бар-, дар-, фуро-, баро-) take no «би-»: баргард!, бардор!, даро!; the stem «о» (омадан) becomes «биё»
const NO_BI = /^(бар|дар|фуро|баро)/;
function biWord(w, compound) {
  if (w === "о") return "биё";
  if (compound || NO_BI.test(w)) return w;
  return w[0] === "о" ? "биё" + w.slice(1) : "би" + w;
}
function tjImper(s, plural, neg) {
  const [pre, w] = lastWord(s);
  const word = pre + (neg ? "на" + (w === "о" ? "ё" : w) : biWord(w, !!pre));
  return word + (plural ? "ед" : "");
}
const tjAgent = (s) => { const [pre, w] = lastWord(s); return pre + w + (endsVowel(w) ? "янда" : "анда"); };
const tjMasdar = (p) => p + "ан";

